import sys
from collections import defaultdict, deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    for _ in range(t):
        try:
            n = int(next(iterator))
            k = int(next(iterator))
        except StopIteration:
            break

        edges1 = []
        edges2 = []

        m1 = int(next(iterator))
        for _ in range(m1):
            u = int(next(iterator))
            v = int(next(iterator))
            edges1.append((u, v))

        m2 = int(next(iterator))
        for _ in range(m2):
            u = int(next(iterator))
            v = int(next.iterator())
            edges2.append((u, v))

        all_edges_set = set()
        for u, v in edges1:
            if u > v:
                u, v = v, u
            all_edges_set.add((u, v))

        for u, v in edges2:
            if u > v:
                u, v = v,u
            all_edges_set.add((u, v))

        adj = defaultdict(list)
        node_set = set()
        for u, v in all_edges_set:
            adj[u].append(v)
            adj[v].append(u)
            node_set.add(u)
            node_set.add(v)

        if len(all_edges_set) != n - 1:
            print("NO")
            continue

        if len(node_set) != n:
            print("NO")
            continue

        start_node = min(node_set)
        visited = set()
        queue = deque([start_node])
        visited.add(start_node)
        count = 0

        while queue:
            u = queue.popleft()
            count += 1
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)

        if count != n:
            print("NO")
            continue

        parent = {}
        order = []
        q = deque([start_node])
        visited_bfs = {start_node}

        while q:
            u = q.popleft()
            order.append(u)
            for v in adj[u]:
                if v not in visited_bfs:
                    visited_bfs.add(v)
                    parent[v] = u
                    q.append(v)

        result_edges = []
        for i in range(1, len(order)):
            u = order[i]
            p = parent[u]
            if u > p:
                result_edges.append((p, u))
            else:
                result_edges.append((u, p))

        print("YES")
        for u, v in result_edges:
            print(f"{u} {v}")

if __name__ == "__main__":
    solve()
